import redis
r = redis.Redis(connection_pool=pool)

def get_feature_vectors(user_id: int, candidate_item_ids: list[int]) -> dict:
    pipe = r.pipeline(transaction=False)
    pipe.hgetall(f"user:{user_id}")              # user features (batch + rt merged)
    for item_id in candidate_item_ids:
        pipe.hgetall(f"item:{item_id}")          # item features
    results = pipe.execute()                       # one network round trip
    user_feats = results[0] or DEFAULT_USER_FEATS  # graceful degradation
    item_feats = {iid: (results[i+1] or DEFAULT_ITEM_FEATS)
                  for i, iid in enumerate(candidate_item_ids)}
    return {"user": user_feats, "items": item_feats}
